import{_ as e,c as r,o as i,a0 as o}from"./chunks/framework.CAcMrZkh.js";const u=JSON.parse('{"title":"BearPlan.Core","description":"","frontmatter":{},"headers":[],"relativePath":"core/introduction.md","filePath":"core/introduction.md"}'),t={name:"core/introduction.md"};function l(n,a,s,d,h,c){return i(),r("div",null,a[0]||(a[0]=[o('<h1 id="bearplan-core" tabindex="-1">BearPlan.Core <a class="header-anchor" href="#bearplan-core" aria-label="Permalink to &quot;BearPlan.Core&quot;">​</a></h1><blockquote><p>BearPlan 的通用框架核心库 —— 抽离权限、缓存、日志、ORM 等通用能力，业务无关、开箱即用，可作为任意 .NET 项目的底层基座。</p></blockquote><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p><code>BearPlan.Core</code> 是 BearPlan 后端架构的最底层基座，承载<strong>与具体业务无关</strong>的框架级基础设施。它不依赖任何业务实体或服务接口，任何 .NET / C# 应用程序都可以直接复用。</p><p>它作为独立仓库维护（<a href="https://gitee.com/BearPlan/BearPlan.NET.Core" target="_blank" rel="noreferrer">gitee.com/BearPlan/BearPlan.NET.Core</a>），已发布为 NuGet 包，可通过 Git Submodule 或 NuGet 引用。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ul><li><strong>🎯 业务中立</strong>：不引用任何业务项目（Entity / IBusiness / Repository / 业务实现），保持纯粹的通用性。</li><li><strong>🧩 开箱即用</strong>：内置缓存、日志、鉴权、AOP、配置、工具类等常用能力，无需从零搭建。</li><li><strong>📦 可独立发布</strong>：作为独立仓库与 NuGet 包演进，版本化、可复用。</li><li><strong>🔗 多种引入方式</strong>：Git Submodule（参与源码编译）或 NuGet 包（二进制引用），按需选择。</li></ul><h2 id="包含能力" tabindex="-1">包含能力 <a class="header-anchor" href="#包含能力" aria-label="Permalink to &quot;包含能力&quot;">​</a></h2><p>按职责划分为五个能力域。每个小模块都可作为独立代码单元直接引用，无需整体引入 Core。</p><h3 id="app-core" tabindex="-1">应用核心 <a class="header-anchor" href="#app-core" aria-label="Permalink to &quot;应用核心 {#app-core}&quot;">​</a></h3><p>承载全局上下文、依赖注入底座与全局配置，是 Core 被引用时最先接触的部分。</p><ul><li id="app-internal"><h4 id="app-internal" tabindex="-1">App / Internal <a class="header-anchor" href="#app-internal" aria-label="Permalink to &quot;&quot;">​</a></h4><p>全局应用入口，统一的服务定位器：<code>App.GetService&lt;T&gt;()</code>、<code>App.GetOptions&lt;T&gt;()</code> 等，让服务与配置在任意位置可用。</p></li><li id="config-options"><h4 id="configoptions" tabindex="-1">ConfigOptions <a class="header-anchor" href="#configoptions" aria-label="Permalink to &quot;ConfigOptions {#config-options}&quot;">​</a></h4><p>强类型配置选项：JWT、Redis、CORS、数据库连接、Serilog、Swagger、中间件开关。</p></li><li id="global"><h4 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;&quot;">​</a></h4><p>全局常量与配置：<code>AppSettings</code>、<code>AuthConstants</code>、<code>MimeTypes</code>、<code>Mapper</code>。</p></li><li id="consts"><h4 id="consts" tabindex="-1">Consts <a class="header-anchor" href="#consts" aria-label="Permalink to &quot;&quot;">​</a></h4><p>通用常量。</p></li><li id="di"><h4 id="di" tabindex="-1">DI <a class="header-anchor" href="#di" aria-label="Permalink to &quot;&quot;">​</a></h4><p>依赖注入基础设施：拦截器、过滤器、Autofac 辅助、DI 标记接口。</p></li></ul><h3 id="aop-middleware" tabindex="-1">AOP 与中间件 <a class="header-anchor" href="#aop-middleware" aria-label="Permalink to &quot;AOP 与中间件 {#aop-middleware}&quot;">​</a></h3><p>横切关注点：基于 Autofac DynamicProxy 的拦截器与 ASP.NET Core 中间件管道。</p><ul><li id="attributes"><h4 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;&quot;">​</a></h4><p>通用特性：缓存、事务、权限、响应格式化、多库路由标记、Redis 订阅。</p></li><li id="aop"><h4 id="aop" tabindex="-1">Aop <a class="header-anchor" href="#aop" aria-label="Permalink to &quot;&quot;">​</a></h4><p>Autofac DynamicProxy 实现的 AOP 拦截器（缓存拦截等）。</p></li><li id="middleware"><h4 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;&quot;">​</a></h4><p>纯中间件：CORS、IP 限流、真实 IP、MiniProfiler、Swagger 授权、404。</p></li></ul><h3 id="cache-log-i18n" tabindex="-1">缓存、日志与多语言 <a class="header-anchor" href="#cache-log-i18n" aria-label="Permalink to &quot;缓存、日志与多语言 {#cache-log-i18n}&quot;">​</a></h3><p>跨业务的基础设施能力：分布式缓存、结构化日志、多语言契约。</p><ul><li id="caches"><h4 id="caches" tabindex="-1">Caches <a class="header-anchor" href="#caches" aria-label="Permalink to &quot;&quot;">​</a></h4><p>缓存抽象与实现：<code>ICache</code>、Redis、分布式缓存、Redis 消息队列。</p></li><li id="serilog"><h4 id="serilog" tabindex="-1">Serilog <a class="header-anchor" href="#serilog" aria-label="Permalink to &quot;&quot;">​</a></h4><p>Serilog 日志输出扩展。</p></li><li id="multi-language"><h4 id="multilanguage" tabindex="-1">MultiLanguage <a class="header-anchor" href="#multilanguage" aria-label="Permalink to &quot;MultiLanguage {#multi-language}&quot;">​</a></h4><p>多语言契约（<code>ILocalizationService</code>、<code>Localizer</code> 资源访问器）。</p></li></ul><h3 id="data-model" tabindex="-1">数据模型与映射 <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;数据模型与映射 {#data-model}&quot;">​</a></h3><p>通用数据契约与对象映射，供 Entity / Repository / Models 共享。</p><ul><li id="model"><h4 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;&quot;">​</a></h4><p>通用模型契约：审计实体接口、分页参数、操作结果。</p></li><li id="pager"><h4 id="pager" tabindex="-1">Pager <a class="header-anchor" href="#pager" aria-label="Permalink to &quot;&quot;">​</a></h4><p>分页相关模型。</p></li><li id="mapping"><h4 id="mapping" tabindex="-1">Mapping <a class="header-anchor" href="#mapping" aria-label="Permalink to &quot;&quot;">​</a></h4><p>对象映射配置（Mapster）。</p></li><li id="enums"><h4 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;&quot;">​</a></h4><p>通用枚举：架构、缓存类型、列类型、部门、字典、性别、菜单、触发器、版本等。</p></li><li id="exception"><h4 id="exception" tabindex="-1">Exception <a class="header-anchor" href="#exception" aria-label="Permalink to &quot;&quot;">​</a></h4><p>通用异常：<code>BusException</code>、<code>BadRequestException</code>。</p></li></ul><h3 id="utils-extensions" tabindex="-1">工具与扩展 <a class="header-anchor" href="#utils-extensions" aria-label="Permalink to &quot;工具与扩展 {#utils-extensions}&quot;">​</a></h3><p>通用算法、扩展方法、工具类与资源文件。</p><ul><li id="extensions"><h4 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;&quot;">​</a></h4><p>扩展方法：字符串、日期、集合、枚举、表达式、字节流、DataTable。</p></li><li id="helper"><h4 id="helper" tabindex="-1">Helper <a class="header-anchor" href="#helper" aria-label="Permalink to &quot;&quot;">​</a></h4><p>工具类：文件、日期、加密（BCrypt/RSA）、HTTP、IP、日志、树结构、Excel、雪花 ID。</p></li><li id="id-generator"><h4 id="idgenerator" tabindex="-1">IdGenerator <a class="header-anchor" href="#idgenerator" aria-label="Permalink to &quot;IdGenerator {#id-generator}&quot;">​</a></h4><p>雪花 ID 生成器。</p></li><li id="class-library"><h4 id="classlibrary" tabindex="-1">ClassLibrary <a class="header-anchor" href="#classlibrary" aria-label="Permalink to &quot;ClassLibrary {#class-library}&quot;">​</a></h4><p>通用算法与工具：一致性哈希、MurmurHash、JSON 转换器、同步集合。</p></li><li id="fonts"><h4 id="fonts" tabindex="-1">Fonts <a class="header-anchor" href="#fonts" aria-label="Permalink to &quot;&quot;">​</a></h4><p>验证码生成所需的字体资源。</p></li></ul><h2 id="关键约束" tabindex="-1">关键约束 <a class="header-anchor" href="#关键约束" aria-label="Permalink to &quot;关键约束&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">核心原则</p><p><code>BearPlan.Core</code> <strong>不得引用任何业务项目</strong>（Entity / IBusiness / Repository / 业务实现），保持业务中立，确保可独立编译与发布。</p></div><p>这意味着：依赖业务实体或服务接口的代码（如数据库种子 <code>SeedService</code>、事务 AOP、日志写库 Sink）即使看起来是&quot;框架设施&quot;，也必须放在上层的 <code>BearPlan.Infrastructure</code>，而不能进入 Core——否则会形成循环依赖。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul><li><strong>运行时</strong>：.NET 10</li><li><strong>ORM 适配</strong>：SqlSugarCore</li><li><strong>缓存</strong>：StackExchange.Redis</li><li><strong>日志</strong>：Serilog（含 Async / Elasticsearch Sink）</li><li><strong>依赖注入</strong>：Autofac（含 DynamicProxy AOP）</li><li><strong>对象映射</strong>：Mapster</li><li><strong>图像处理</strong>：SixLabors.ImageSharp</li><li><strong>任务调度</strong>：Quartz</li><li><strong>其它</strong>：Newtonsoft.Json、NodaTime、MiniProfiler、Swashbuckle</li></ul><h2 id="关联资源" tabindex="-1">关联资源 <a class="header-anchor" href="#关联资源" aria-label="Permalink to &quot;关联资源&quot;">​</a></h2><ul><li><strong>Core 仓库</strong>：<a href="https://gitee.com/BearPlan/BearPlan.NET.Core" target="_blank" rel="noreferrer">https://gitee.com/BearPlan/BearPlan.NET.Core</a></li><li><strong>主项目</strong>：<a href="https://gitee.com/BearPlan/BearPlan.NET" target="_blank" rel="noreferrer">https://gitee.com/BearPlan/BearPlan.NET</a></li><li><strong>开发文档</strong>：<a href="https://bear.js.org/" target="_blank" rel="noreferrer">https://bear.js.org/</a></li><li><strong>作者微信</strong>：Byte_Xiong（备注：框架）</li></ul><p>准备好开始使用？前往 <a href="/core/quickstart.html">快速开始</a> 了解引入方式。</p>',32)]))}const g=e(t,[["render",l]]);export{u as __pageData,g as default};
